// readCounter implements ReadCounter by wrapping an io.Reader and
// counting the bytes and operations of each successful Read.
type readCounter struct {
	reader io.Reader

	mu     sync.Mutex
	n      int64
	nops   int
}

// writeCounter implements WriteCounter by wrapping an io.Writer and
// counting the bytes and operations of each successful Write.
type writeCounter struct {
	writer io.Writer

	mu   sync.Mutex
	n    int64
	nops int
}

// readWriteCounter implements ReadWriteCounter by combining a readCounter
